const battlesData=[{id:"hydaspes",name:"Battle of the Hydaspes",year:-326,date:"May 326 BCE",century:"4th BCE",dynasty:"Paurava / Alexander",region:"North",winner:"Macedonian Victory",location:"Hydaspes River (Jhelum)",summary:"Tactical clash between Alexander the Great and King Porus featuring war elephant charges and monsoon river crossing.",link:"../battle-of-hydaspes-explorer/index.html"},{id:"mauryan-seleucid",name:"Mauryan–Seleucid War",year:-305,date:"305–303 BCE",century:"4th BCE",dynasty:"Maurya",region:"North",winner:"Maurya",location:"Indus Valley",summary:"Emperor Chandragupta Maurya defeated Seleucus I Nicator, gaining four satrapies and establishing imperial boundary peace.",link:"../mauryan-seleucid-war-explorer/index.html"},{id:"kalinga",name:"Battle of Kalinga",year:-261,date:"261 BCE",century:"3rd BCE",dynasty:"Maurya",region:"East",winner:"Maurya",location:"Kalinga (Odisha)",summary:"Transformative battle that led Emperor Ashoka to renounce military conquest and embrace Buddhist Dhamma.",link:"../kalinga-war-explorer/index.html"},{id:"chandawar",name:"Battle of Chandawar",year:1194,date:"1194 CE",century:"12th CE",dynasty:"Ghurid / Sultanate",region:"North",winner:"Sultanate",location:"Yamuna River near Etawah",summary:"Decisive Ghurid victory by Muhammad Ghori over King Jayachandra of the Gahadavala Dynasty.",link:"../battle-of-chandawar-explorer/index.html"},{id:"devagiri",name:"Battle of Devagiri",year:1296,date:"1296 CE",century:"13th CE",dynasty:"Ghurid / Sultanate",region:"Central",winner:"Sultanate",location:"Devagiri (Maharashtra)",summary:"Alauddin Khalji’s surprise raid across the Vindhyas opening South India to Delhi Sultanate campaigns.",link:"../battle-of-devagiri-explorer/index.html"},{id:"kili",name:"Battle of Kili",year:1299,date:"1299 CE",century:"13th CE",dynasty:"Ghurid / Sultanate",region:"North",winner:"Sultanate",location:"Kili, near Delhi",summary:"Sultan Alauddin Khalji repelled Qutlugh Khwaja’s 200,000-strong Chagatai Mongol invasion force.",link:"../battle-of-kili-explorer/index.html"},{id:"first-panipat",name:"First Battle of Panipat",year:1526,date:"21 April 1526",century:"16th CE",dynasty:"Mughal",region:"North",winner:"Mughal",location:"Panipat, Haryana",summary:"Babur used field artillery and Tulughma tactics to defeat Ibrahim Lodi and establish the Mughal Empire.",link:"../first-battle-of-panipat-explorer/index.html"},{id:"haldighati",name:"Battle of Haldighati",year:1576,date:"18 June 1576",century:"16th CE",dynasty:"Mughal",region:"West",winner:"Mughal",location:"Haldighati, Rajasthan",summary:"Legendary clash between Maharana Pratap of Mewar and Akbar’s army led by Man Singh I.",link:"../battle-of-haldighati-explorer/index.html"},{id:"colachel",name:"Battle of Colachel",year:1741,date:"10 August 1741",century:"18th CE",dynasty:"Travancore",region:"South",winner:"Travancore Victory",location:"Colachel, Kanyakumari",summary:"King Marthanda Varma of Travancore defeated the Dutch East India Company, ending Dutch naval dominance.",link:"../battle-of-colachel-explorer/index.html"},{id:"plassey",name:"Battle of Plassey",year:1757,date:"23 June 1757",century:"18th CE",dynasty:"East India Company",region:"East",winner:"Company",location:"Palashi, Bengal",summary:"Robert Clive defeated Nawab Siraj-ud-Daulah, initiating British political hegemony over Bengal and India.",link:"../battle-of-plassey-explorer/index.html"},{id:"buxar",name:"Battle of Buxar",year:1764,date:"22 October 1764",century:"18th CE",dynasty:"East India Company",region:"East",winner:"Company",location:"Buxar, Bihar",summary:"Hector Munro routed the combined forces of Bengal, Awadh, and Mughal Emperor Shah Alam II.",link:"../battle-of-buxar-explorer/index.html"},{id:"kannauj",name:"Battle of Kannauj (Bilgram)",year:1540,date:"17 May 1540",century:"16th CE",dynasty:"Sur / Mughal",region:"North",winner:"Suri",location:"Kannauj, Uttar Pradesh",summary:"Sher Shah Suri defeated Mughal Emperor Humayun, ending the first Mughal reign and establishing the Sur Empire in North India.",link:"../battle-of-kannauj-explorer/index.html"}];function initTheme(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const a=document.body.classList.contains("light-theme");localStorage.setItem("theme",a?"light":"dark"),e.textContent=a?"☀️":"🌙"})}function initFilterListeners(){["battle-search","filter-century","filter-dynasty","filter-region","filter-winner"].forEach(e=>{const a=document.getElementById(e);a&&(a.addEventListener("input",renderBattles),a.addEventListener("change",renderBattles))})}function renderBattles(){const e=document.getElementById("battles-container"),a=document.getElementById("results-count"),t=document.getElementById("no-results"),n=document.getElementById("battle-search").value.toLowerCase(),i=document.getElementById("filter-century").value,r=document.getElementById("filter-dynasty").value,l=document.getElementById("filter-region").value,d=document.getElementById("filter-winner").value,o=battlesData.filter(e=>{const a=e.name.toLowerCase().includes(n)||e.location.toLowerCase().includes(n)||e.summary.toLowerCase().includes(n),t="all"===i||e.century===i,o="all"===r||e.dynasty.includes(r),s="all"===l||e.region===l,u="all"===d||e.winner.includes(d);return a&&t&&o&&s&&u});0===o.length?(e.innerHTML="",t.style.display="block",a.textContent="No matching battles found"):(t.style.display="none",a.textContent=`Showing ${o.length} of ${battlesData.length} battles`,e.innerHTML=o.map(e=>`\n      <div class="battle-card">\n        <div>\n          <div class="card-header-meta">\n            <span class="badge-century">${e.century}</span>\n            <span class="badge-region">📍 ${e.region} India</span>\n          </div>\n          <h3>${e.name}</h3>\n          <div class="battle-card-date">🗓️ ${e.date}</div>\n          <p class="battle-card-summary">${e.summary}</p>\n        </div>\n        <div>\n          <div class="battle-card-meta">\n            <div><strong>Location:</strong> ${e.location}</div>\n            <div><strong>Outcome:</strong> ${e.winner}</div>\n          </div>\n          <a href="${e.link}" class="btn-explore">Explore Battle Details →</a>\n        </div>\n      </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");if(!e)return;const a=[...battlesData].sort((e,a)=>e.year-a.year);e.innerHTML=a.map(e=>`\n    <div class="timeline-item">\n      <div class="timeline-dot"></div>\n      <div class="timeline-content">\n        <span class="timeline-year">${e.date}</span>\n        <h4>${e.name}</h4>\n        <p>${e.summary}</p>\n      </div>\n    </div>\n  `).join("")}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initFilterListeners(),renderBattles(),renderTimeline()});